/* Export the square SVG layouts generated by compose-community-post.py.
 * Requires Sharp, passed through NODE_PATH or installed in the environment.
 */
const fs = require('fs');
const path = require('path');
const sharp = require('sharp');
const root = path.resolve(process.argv[2] || '.');
const source = path.join(root, 'build/workshop-0.10.0/community-post');
const out = path.join(root, 'art/social/0.10.0');
const names = [
  'hart-street-food-community-square',
  'hart-street-food-02-new-foods-square',
  'hart-street-food-03-kitchen-square',
  'hart-street-food-04-treats-square',
  'hart-street-food-05-truck-square',
];
async function main() {
  fs.mkdirSync(out, {recursive:true});
  for (const name of names) {
    const input = path.join(source, name+'.svg');
    await sharp(input).png({compressionLevel:9}).toFile(path.join(out,name+'.png'));
    await sharp(input).jpeg({quality:95,chromaSubsampling:'4:4:4'}).toFile(path.join(out,name+'.jpg'));
    await sharp(input).resize(400,400).png().toFile(path.join(source,name+'-mobile.png'));
    console.log('EXPORTED', name);
  }
  const tiles = [];
  for (let i=0;i<4;i++) {
    tiles.push({input:await sharp(path.join(out,names[i+1]+'.png')).resize(800,800).png().toBuffer(),left:(i%2)*800,top:Math.floor(i/2)*800});
  }
  await sharp({create:{width:1600,height:1600,channels:3,background:'#F7F5ED'}}).composite(tiles).jpeg({quality:95,chromaSubsampling:'4:4:4'}).toFile(path.join(out,'showcase-overview.jpg'));
}
main().catch(e=>{console.error(e);process.exitCode=1;});
